package com.rhay.pkgexplorer;
import android.app.*; import android.os.*; import android.content.*; import android.net.Uri; import android.graphics.Color; import android.view.*; import android.widget.*; import java.io.*; import java.nio.charset.StandardCharsets; import java.util.Locale;
public class MainActivity extends Activity {
 private static final int PICK=1,SAVE=2; private Uri file; private TextView output,status; private String report="";
 private LinearLayout root;
 public void onCreate(Bundle b){super.onCreate(b); ScrollView scroll=new ScrollView(this); root=new LinearLayout(this);root.setOrientation(1);root.setPadding(20,28,20,20);root.setBackgroundColor(Color.rgb(12,18,30));scroll.addView(root);setContentView(scroll);
 TextView title=text("RHAY PKG EXPLORER",24);title.setTextColor(Color.CYAN);root.addView(title);root.addView(text("Analisador de PKG • leitura sem modificar o original",14));
 button("Selecionar PKG",()->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,PICK);});
 button("Analisar cabeçalho",()->analyze(false));button("Buscar nomes na amostra (32 MB)",()->analyze(true));button("Salvar relatório TXT",()->{if(report.isEmpty()){toast("Analise primeiro");return;}Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("text/plain");i.putExtra(Intent.EXTRA_TITLE,"rhay_pkg_relatorio.txt");startActivityForResult(i,SAVE);});
 status=text("Nenhum arquivo selecionado",14);root.addView(status);output=text("Este aplicativo não descriptografa PKGs nem extrai arquivos protegidos.",13);output.setTextIsSelectable(true);root.addView(output);}
 private TextView text(String s,int size){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(-1);t.setPadding(8,12,8,12);return t;}
 private void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);root.addView(b);b.setOnClickListener(v->r.run());}
 private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK||data==null)return;if(req==PICK){file=data.getData();status.setText("Arquivo selecionado: "+file);try{getContentResolver().takePersistableUriPermission(file,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}}else if(req==SAVE){try(OutputStream o=getContentResolver().openOutputStream(data.getData())){o.write(report.getBytes(StandardCharsets.UTF_8));toast("Relatório salvo");}catch(Exception e){toast(e.toString());}}}
 private void analyze(boolean scan){if(file==null){toast("Selecione o PKG");return;}status.setText("Lendo arquivo...");new Thread(()->{String r;try{r=read(scan);}catch(Exception e){r="Erro: "+e.toString();}final String result=r;runOnUiThread(()->{report=result;output.setText(result);status.setText("Análise concluída");});}).start();}
 private String read(boolean scan)throws IOException{StringBuilder sb=new StringBuilder("RHAY PKG Explorer 1.0\n"+file+"\n");byte[] h=new byte[512];int n=0;try(InputStream in=getContentResolver().openInputStream(file)){while(n<h.length){int c=in.read(h,n,h.length-n);if(c<0)break;n+=c;}}sb.append("Bytes do cabeçalho: "+n+"\n");for(int i=0;i<n;i+=16){sb.append(String.format(Locale.US,"%08X  ",i));for(int j=i;j<Math.min(n,i+16);j++)sb.append(String.format(Locale.US,"%02X ",h[j]&255));sb.append("\n");}if(n>=4){sb.append("Assinatura: ");for(int i=0;i<4;i++)sb.append(String.format(Locale.US,"%02X ",h[i]&255));sb.append("\n");if((h[0]&255)==127&&h[1]=='C'&&h[2]=='N'&&h[3]=='T')sb.append("Possível PKG PS4 CNT\n");}
 if(scan){sb.append("\nOcorrências na amostra de 32 MB:\n");byte[] b=new byte[65536];StringBuilder s=new StringBuilder();long pos=0;int hits=0;try(InputStream in=getContentResolver().openInputStream(file)){int count;while(pos<33554432&&(count=in.read(b,0,(int)Math.min(b.length,33554432-pos)))!=-1){for(int i=0;i<count;i++){int v=b[i]&255;if(v>=32&&v<=126){if(s.length()<200)s.append((char)v);}else{String z=s.toString().toLowerCase(Locale.ROOT);if(hits<100&&(z.contains(".fmdl")||z.contains(".fpk")||z.contains(".ftex")||z.contains(".cpk")||z.contains("face"))){sb.append("0x"+Long.toHexString(pos+i-s.length())+": "+s+"\n");hits++;}s.setLength(0);}}pos+=count;}}sb.append("Bytes examinados: "+pos+"; ocorrências: "+hits+"\n");}sb.append("\nNão extrai conteúdo criptografado.\n");return sb.toString();}
}
